CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE app_user (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, password_hash text NOT NULL, display_name text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE CHECK (code IN ('ADMIN','CASHIER')), name text NOT NULL);
INSERT INTO role(code,name) VALUES ('ADMIN','Admin'),('CASHIER','Cashier') ON CONFLICT (code) DO NOTHING;
CREATE TABLE user_role (user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, role_id uuid NOT NULL REFERENCES role(id) ON DELETE RESTRICT, granted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role_id));
CREATE TABLE refresh_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku text NOT NULL UNIQUE, barcode text UNIQUE, name text NOT NULL, description text, unit text NOT NULL DEFAULT 'each', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX product_name_idx ON product USING gin (to_tsvector('simple', name));
CREATE TABLE product_price (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, amount numeric(12,2) NOT NULL CHECK(amount >= 0), currency char(3) NOT NULL, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, CHECK(effective_to IS NULL OR effective_to > effective_from));
CREATE INDEX product_price_active_idx ON product_price(product_id,effective_from DESC) WHERE effective_to IS NULL;
CREATE TABLE supplier (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, contact_name text, phone text, email text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_lot (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, supplier_id uuid REFERENCES supplier(id) ON DELETE RESTRICT, lot_code text NOT NULL, expires_on date, received_at timestamptz NOT NULL DEFAULT now(), unit_cost numeric(12,2) NOT NULL CHECK(unit_cost >= 0), qty_received numeric(14,3) NOT NULL CHECK(qty_received > 0), qty_on_hand numeric(14,3) NOT NULL CHECK(qty_on_hand >= 0), is_active boolean NOT NULL DEFAULT true, UNIQUE(product_id,lot_code));
CREATE INDEX inventory_fefo_idx ON inventory_lot(product_id,expires_on,received_at) WHERE is_active AND qty_on_hand > 0;
CREATE TABLE sale (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_number text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('COMPLETED','VOIDED')), cashier_user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, customer_name_snapshot text, subtotal numeric(12,2) NOT NULL CHECK(subtotal >= 0), discount_total numeric(12,2) NOT NULL DEFAULT 0 CHECK(discount_total >= 0), tax_total numeric(12,2) NOT NULL DEFAULT 0 CHECK(tax_total >= 0), total numeric(12,2) NOT NULL CHECK(total >= 0), currency char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), voided_at timestamptz, voided_by uuid REFERENCES app_user(id) ON DELETE RESTRICT, void_reason text);
CREATE TABLE sale_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sale(id) ON DELETE RESTRICT, product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, sku_snapshot text NOT NULL, name_snapshot text NOT NULL, quantity numeric(14,3) NOT NULL CHECK(quantity > 0), unit_price numeric(12,2) NOT NULL CHECK(unit_price >= 0), discount_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(discount_amount >= 0), tax_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(tax_amount >= 0), line_total numeric(12,2) NOT NULL CHECK(line_total >= 0));
CREATE TABLE sale_item_lot (sale_item_id uuid NOT NULL REFERENCES sale_item(id) ON DELETE RESTRICT, lot_id uuid NOT NULL REFERENCES inventory_lot(id) ON DELETE RESTRICT, quantity numeric(14,3) NOT NULL CHECK(quantity > 0), PRIMARY KEY(sale_item_id,lot_id));
CREATE TABLE payment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sale(id) ON DELETE RESTRICT, method text NOT NULL CHECK(method IN ('CASH','CARD','E_WALLET','OTHER')), amount numeric(12,2) NOT NULL CHECK(amount > 0), currency char(3) NOT NULL, status text NOT NULL CHECK(status IN ('CAPTURED','REFUNDED','REVERSED')), reference text, received_at timestamptz NOT NULL DEFAULT now(), recorded_by uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, reverses_payment_id uuid REFERENCES payment(id) ON DELETE RESTRICT);
CREATE TABLE stock_movement (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES product(id) ON DELETE RESTRICT, lot_id uuid REFERENCES inventory_lot(id) ON DELETE RESTRICT, movement_type text NOT NULL CHECK(movement_type IN ('RECEIPT','SALE','ADJUSTMENT_IN','ADJUSTMENT_OUT','REVERSAL')), quantity_delta numeric(14,3) NOT NULL CHECK(quantity_delta <> 0), reference_type text, reference_id uuid, reason text, actor_user_id uuid REFERENCES app_user(id) ON DELETE RESTRICT, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX stock_movement_product_time_idx ON stock_movement(product_id,occurred_at DESC);
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES app_user(id) ON DELETE RESTRICT, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, request_id text, details jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_entity_time_idx ON audit_log(entity_type,entity_id,occurred_at DESC);
CREATE TABLE idempotency_record (cashier_user_id uuid NOT NULL REFERENCES app_user(id) ON DELETE RESTRICT, endpoint text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, response_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(cashier_user_id,endpoint,idempotency_key));
